    if lhs.rotation != rhs.rotation {return false}
    if lhs.width != rhs.width {return false}
    if lhs.height != rhs.height {return false}
    if lhs.insetsTop != rhs.insetsTop {return false}
    if lhs.insetsLeft != rhs.insetsLeft {return false}
    if lhs.insetsRight != rhs.insetsRight {return false}
    if lhs.insetsBottom != rhs.insetsBottom {return false}
    if lhs.flipHorizontally != rhs.flipHorizontally {return false}
    if lhs.flipVertically != rhs.flipVertically {return false}
    if lhs.alphaType != rhs.alphaType {return false}
    if lhs.useDefaultNativeRotation != rhs.useDefaultNativeRotation {return false}
    if lhs.unknownFields != rhs.unknownFields {return false}
    return true
  }
}
